package router

import (
	"github.com/gin-gonic/gin"

	"svn.danawa.com/sapi/controller"
)

// ProductRegister godoc
func (r *Router) ProductRegister(router *gin.RouterGroup) {
	c := controller.NewController()

	router.GET("/list", c.ProductList)                           // 상품 리스트 API(/product/NewProductList)
	router.GET("/uicategory/option", c.UICategoryOption)         // UI카테고리 검색옵션 API(/product/NewUiSearchOption)
	router.GET("/category/option", c.CategoryOption)             // 물리카테고리및 뎁스를  이용한 검색옵션 API(/product/NewSearchOption)
	router.GET("/plan", c.ProductPlan)                           // 기획전 검색상품 조회용 API(/product/PlanShop)
	router.GET("/office/main", c.OfficeMain)                     // 오피스 기준상품 검색(/product/OfficeMainProductSearch)
	router.GET("/office/link", c.OfficeLink)                     // 오피스 링크 검색(/product/OfficeMainProductSearch)
	router.GET("/mall", c.MallGroup)                             // 제휴몰 그룹핑 API(/product/MallGroup)
	router.GET("/category", c.CategoryGroup)                     // 카테고리 그룹핑 API(/product/CategoryGroup)
	router.GET("/makerBrand", c.MakerBrandGroup)                 // 카테고리 그룹핑 API(/product/CategoryGroup)
	router.GET("/uicategory/makerBrand", c.UICategoryMakerBrand) // UI카테고리 설정 값을 활용한 제조사 브랜드 그룹핑 API(/product/NewMakerBrandCodeGroup)
	router.GET("/search", c.ProductSearch)                       // 통합검색
	//router.GET("/office/main/test", c.OfficeMainTest)            // 오피스 기준상품 검색(/product/OfficeMainProductSearch)

	//OPENAPI에서 JSON 확장자가 포함되어 호출됨에 따라 추가
	router.GET("/category/option.json", c.CategoryOption) // 물리카테고리및 뎁스를  이용한 검색옵션 API(/product/NewSearchOption)

	// 상품데이터관리개선 V2.0
	router.GET("/unlink", c.ProductUnlinkV3) // 미링크 상품 조회 API

	// 상품데이터관리개선 V3.0
	router.GET("/v3/unlink", c.ProductUnlinkV3)       // 미링크 상품 조회 API
	router.GET("/v3/office/unlink", c.OfficeUnlinkV3) // 오피스 미링크 검색 api

	// [FASTCAT-1176] 상품리스트 사이즈 검색 기능 추가
	router.GET("/category/size", c.CategorySize) // 카테고리내 상품사이즈 조회 API(/category/size)
	router.GET("/attribute", c.ProductAttribute) // 상품 속성 코드 조회 API(/attribute)

	router.GET("/attribute/value", c.ProductAttributeValue) // 상품 속성, 속성 값 설명 조회 API

	router.GET("/member-price-lower", c.ProductMemberPriceLower) // 멤버쉽 최저가 상품 조회 API
}

func (c *Controller) ProductSearch(ctx *gin.Context) {
	startTime := time.Now()
	ctx.Keys = make(map[string]interface{})
	ctx.Keys["cache"] = ""

	resp := response.Response{}

	// 2022.04.27 author. Kim yungi
	// 프론트에서 html entity를 escape하여 보내주기 때문에 keyword 다시 unescape 처리
	keyword := html.UnescapeString(ctx.Query("keyword"))
	start := utils.CheckIntData(ctx.DefaultQuery("start", "1"))

	if len(keyword) == 0 && len(ctx.Query("cate1")) == 0 && len(ctx.Query("productCode")) == 0 {
		resp.Status = http.StatusBadRequest
		resp.Desc = "keyword or cate1 or productCode must required"

		ctx.JSON(http.StatusOK, resp)

		return
	} else if !utils.KeywordLengthCheck(keyword) && len(ctx.Query("cate1")) == 0 && len(ctx.Query("productCode")) == 0 {
		// } else if !utils.KeywordLengthCheck(keyword) {
		resp.Status = http.StatusBadRequest
		resp.Desc = "keyword must be greater than 1 byte"

		ctx.JSON(http.StatusOK, resp)

		return
	} else if len(keyword) >= 100 {
		resp.Status = http.StatusBadRequest
		resp.Desc = "keyword must be less than 35 characters"

		ctx.JSON(http.StatusBadRequest, resp)

		return
	} else if start < 0 {
		resp.Status = http.StatusBadRequest
		resp.Desc = "start must be greater than zero"

		ctx.JSON(http.StatusOK, resp)

		return
	} else if ctx.Query("volume") == "va" && (len(ctx.Query("maker")) > 0 || len(ctx.Query("brand")) > 0 || len(ctx.Query("avSeq")) > 0) {
		//검색상품에 검색옵션이 사용되면 결과는 항상 0이므로 그대로 반환한다.
		resp.Status = http.StatusOK
		resp.Result = response.Result{
			Keyword:     ctx.Query("keyword"),
			Time:        "0 ms",
			Total_count: 0,
			Count:       0,
			//SearchList: make([]interface{}, 0),
		}
		//resp.Desc = "cannot use maker, brand, avSeq when volume is va"
		ctx.JSON(http.StatusOK, resp)

		return
	}

	boost := ctx.Query("boost")
	var attributeValueSeqBoost string
	if ctx.Query("boostYN") == "Y" && ctx.Query("countYN") != "Y" { //부스팅 카테고리 여부가 Y일 경우 해당 키워드에 대한 부스트필터 적용, 카운트용 쿼리 제외
		if categoryBoosts, err := handler.GetBoostCategoryHandler(keyword); err != nil { // 에러인경우 검색엔진 호출
			if err.Error() != "redis: nil" { // redis: nil 데이터가 없을경우
				boost = handler.GetBoostDataEs(keyword)
				// boost = strings.Join(handler.GetBoostData(keyword), " ")
			}
		} else { // redis 값이 있을 경우
			// [catec|depth|weighting, catec|depth|weighting] -> [catec,depth,weighting catec,depth,weighting] 으로

			for _, categoryBoost := range strings.Split(categoryBoosts, ",") {
				boost = boost + strings.ReplaceAll(categoryBoost, "|", ",") + " "
			}
			boost = boost[:len(boost)-1]
		}

		if attributeValueSeq, err := handler.GetAttributeValueSeqBoostHandler(keyword); err == nil {
			for _, value := range strings.Split(attributeValueSeq, ",") {
				attributeValueSeqBoost += strings.ReplaceAll(value, "|", ",") + " "
			}
			attributeValueSeqBoost = attributeValueSeqBoost[:len(attributeValueSeqBoost)-1]
		}
	}

	//boostTime := time.Since(startTime)
	//utils.Logger.Info("[controller] boostTime: %s\n", boostTime)

	// 상품검색 서비스의 페이지 탐색 범위 제한 방안
	limit := utils.CheckIntData(ctx.DefaultQuery("limit", "20"))

	limitStart, limitOffset, isLimit := utils.PageSearchRangeLimit(start, limit)
	limitOffset = utils.LimitControl(limitOffset)

	//pageLimitTime := time.Since(startTime)
	//utils.Logger.Info("[controller] pageLimitTime: %s\n", pageLimitTime)

	query := make(map[string]string)

	query["volume"] = ctx.Query("volume")
	query["field"] = ctx.DefaultQuery("field", "prod_id")
	query["start"] = strconv.Itoa(limitStart)
	query["limit"] = strconv.Itoa(limitOffset)
	query["keyword"] = html.UnescapeString(ctx.Query("keyword"))
	query["addSearchKeyword"] = ctx.Query("addSearchKeyword")
	query["subKeyword"] = ctx.Query("subKeyword")
	query["uiCateKeyword"] = ctx.Query("uiCateKeyword")
	query["target"] = ctx.DefaultQuery("target", "total")
	query["cate1"] = ctx.DefaultQuery("cate1", "0")
	query["cate2"] = ctx.Query("cate2")
	query["cate3"] = ctx.Query("cate3")
	query["cate4"] = ctx.Query("cate4")
	query["cateCode"] = ctx.Query("cateCode")
	query["attributeOptionCode"] = ctx.Query("attributeOptionCode") // 검색옵션
	query["makerOptionCode"] = ctx.Query("makerOptionCode")         // 제조사코드
	query["makerOptionName"] = ctx.Query("makerOptionName")         // 제조사명
	query["brandOptionCode"] = ctx.Query("brandOptionCode")         // 브랜드코드
	query["brandOptionName"] = ctx.Query("brandOptionName")         // 브랜드명
	query["cateExclude"] = ctx.Query("cateExclude")
	query["makerName"] = ctx.Query("makerName")
	query["brandName"] = ctx.Query("brandName")
	query["useBrandNameYN"] = ctx.DefaultQuery("useBrandNameYN", "N")
	query["makerBrandName"] = ctx.Query("makerBrandName")
	query["shopCode"] = ctx.Query("shopCode")
	query["productCode"] = ctx.Query("productCode")
	query["shotYN"] = ctx.Query("shotYN")
	query["packageYN"] = ctx.DefaultQuery("packageYN", "N") // 일반리스트
	query["imgSize"] = ctx.DefaultQuery("imgSize", "80")
	query["shop"] = ctx.Query("shop")
	query["boost"] = boost
	query["attributeValueSeqBoost"] = attributeValueSeqBoost
	query["countYN"] = ctx.DefaultQuery("countYN", "N")         // 갯수확인 여부 (일반)
	query["highlightYN"] = ctx.DefaultQuery("highlightYN", "Y") // 하이라이트 처리
	query["synonymYN"] = ctx.DefaultQuery("synonymYN", "N")     // 동의어 확장
	query["displayYN"] = ctx.DefaultQuery("displayYN", "Y")     // 노출 설정된 상품
	query["loggingYN"] = ctx.DefaultQuery("loggingYN", "N")     // 검색 키워드 로그분석 처리 안함.
	query["userId"] = ctx.DefaultQuery("userId", "guest")
	query["userAge"] = ctx.DefaultQuery("userAge", "0")
	query["userGender"] = ctx.DefaultQuery("userGender", "0")
	query["previousKeyword"] = ctx.Query("previousKeyword")
	query["service"] = ctx.DefaultQuery("service", "0")
	query["keywordType"] = ctx.DefaultQuery("keywordType", "1")
	query["sort"] = ctx.DefaultQuery("sort", "9")
	query["priceRange"] = ctx.Query("priceRange")
	query["totalPriceRange"] = ctx.Query("totalPriceRange")
	query["boostYN"] = ctx.DefaultQuery("boostYN", "N")
	query["compareYN"] = ctx.DefaultQuery("compareYN", "N")
	query["zeroPriceYN"] = ctx.Query("zeroPriceYN")             // 0원상품 제외
	query["registerDateRange"] = ctx.Query("registerDateRange") // 등록년월

	query["maker"] = ctx.Query("maker")
	query["brand"] = ctx.Query("brand")
	query["avSeq"] = ctx.Query("avSeq")

	query["width"] = ctx.Query("width")   // 가로 사이즈
	query["depth"] = ctx.Query("depth")   // 세로 사이즈
	query["height"] = ctx.Query("height") // 높이 사이즈

	query["excludeShopCode"] = ctx.Query("excludeShopCode")
	query["brandCateYN"] = ctx.DefaultQuery("brandCateYN", "N")

	query["debug"] = ctx.DefaultQuery("debug", "0")
	query["userAgent"] = ctx.GetHeader("User-Agent")
	query["referer"] = ctx.DefaultQuery("referer", "0")

	query["mobileStoreYN"] = ctx.Query("mobileStoreYN")
	query["quickProductYN"] = ctx.DefaultQuery("quickProductYN", "N")

	if utils.KeywordValidCheck(keyword) == false {
		resp.Status = http.StatusBadRequest
		resp.Desc = "keyword should not be url."
	} else if isLimit == true { // 페이지 탐색범위 제한 걸렸으면 캐쉬데이터 가져오기 (키워드&카테고리)

		ctx.Query(keyword)
		// 키워드_카테고리코드_카운트유무(Y,N)
		//PROUDCT:SEARCH:VOLUME:KEYWORD:CATEGORY:SORT:LIMIT

		cateList := []string{query["cate1"], query["cate2"], query["cate3"], query["cate4"]}
		redisKey := make([]string, 0)

		// redisKey := query["volume"] + ":" + query["keyword"]
		redisKey = append(redisKey, query["volume"])
		redisKey = append(redisKey, query["keyword"])

		intCate := utils.GetCategoryCode(cateList)
		// if intCate > 0 {
		redisKey = append(redisKey, strconv.Itoa(intCate))
		// }

		redisKey = append(redisKey, query["sort"])

		if result, err := handler.GetLimitProductRedisHandler("SEARCH", strings.Join(redisKey, ":"), limitOffset); err != nil {
			// if err.Error() == "redis: nil" {
			if err == redis.Nil { // 데이터 없음
				// 1. 검색엔진에서 데이터 가져옴
				if data, err := handler.ProductSearchES(query); err != nil {
					resp.Status = http.StatusInternalServerError
					resp.Desc = err.Error()
