// ProductSearchES godoc
func ProductSearchES(data map[string]string) (result response.Result, err error) {
	//debug용 esquey
	//var esQuery []string
	var boostDataArr []string
	var fsc *elastic.FetchSourceContext
	var fieldSorts []elastic.Sorter
	var highlight *elasticSearch.Highlight
	var sourceList []string

	//묶음상품 처리
	var collaspeBuilder *elasticSearch.CollapseBuilder
	var aggrs *elasticSearch.CardinalityAggregation
	var innerHit *elasticSearch.InnerHit

	keyword := data["keyword"]

	//Category Boost
	if len(data["boost"]) > 0 {
		boostDataArr = utils.ConvertBoostDataEs(data["boost"])
	}

	//카테고리 처리
	seCateList := [4]string{data["cate1"], data["cate2"], data["cate3"], data["cate4"]}

	seCate := ""
	if len(data["keyword"]) == 0 {
		for key, cate := range seCateList {
			if utils.CheckIntData(cate) > 0 {
				seCate = fmt.Sprintf("%d_%s", key+1, cate)
			}
		}
	}

	data["seCate"] = seCate

	mainFunctionQuery := elasticSearch.NewFunctionScoreQuery()

	///////////////handler/////////////

	//카운트쿼리 여부
	countYN := data["countYN"]

	//인덱스(volume)
	index := utils.GetCollectionListEsVolume(data["volume"])
	if data["volume"] == "all" || data["volume"] == "va" {
		index += ",danawapc2"
	}
	if data["volume"] == "va" && data["brandCateYN"] == "Y" {
		index += ",s-prod-link"
	}
	/*
	 * s-prod, danawaPc2 인덱스는
	 * unitLowPrice, unitTotalPrice, unitMemberPrice, unitMemberTotalPrice
	 * 필드가 없으므로 해당 필드로 정렬시 강제로 index를 기준상품으로 고정한다.
	 */
	intSort, _ := strconv.Atoi(data["sort"])
	if intSort >= 20 && intSort <= 27 {
		if data["countYN"] == "N" {
			index = "main-prod-vm"
		}
	}
	//검색 시작값
	from, _ := strconv.Atoi(data["start"])

	//검색 갯수
	size, _ := strconv.Atoi(data["limit"])

	debug := utils.CheckIntData(data["debug"])

	//searchQuery
	query := product.ProductSearchBoolQuery(data, index)

	if countYN == "Y" {
		//갯수 지정
		//_Count를 안쓰는 이유는 /_Count에는 Collapse(묶음검색)을 줄 수 없다..
		size = 0
		from = 1
		fsc = elastic.NewFetchSourceContext(false)
	} else {
		//검색 field
		sourceList = product.ProductSearchSource(data["field"])

		fsc = elastic.NewFetchSourceContext(true).Include(sourceList...)

		//정렬
		fieldSorts = product.ProductSearchSort(data["sort"])

		//하이라이팅
		var highlightKeyword string
		if data["highlightYN"] == "Y" && len(keyword) > 0 {

			highlightKeyword = keyword
			if len(data["addSearchKeyword"]) > 0 {
				highlightKeyword = keyword + " " + data["addSearchKeyword"]
			}

			fields := []string{
				"productName",
				"simpleDescription",
				"mobileDescription",
				"productModel",
				"productBrand",
				"brandKeyword",
				"productMaker",
				"makerKeyword",
				"categoryWeight",
				"managerKeyword",
				"bundleName",
				"relationModel"}

			//highlight = SetHighLight(keyword)
			highlight = common.Highlight2(fields, "Y", "", highlightKeyword)
		}

		//부스팅 Redis 호출
		if len(boostDataArr) > 0 {
			/**
			ex)
			boostDataArr[0] = "categoryCode1:860:300000"
			boostDataArr[1] = "categoryCode2:32617:100000"
			*/
			//for i := 0; i < len(boostDataArr); i++ {
			//	boostData := strings.Split(boostDataArr[i], ":")
			//
			//	//카테고리 부스팅 데이터가 정상적일 때만 쿼리 생성
			//	if len(boostData) == 3 {
			//		categoryDepth := boostData[0]
			//		boostScore, _ := strconv.ParseFloat(boostData[2], 64)
			//		category, _ := strconv.ParseFloat(boostData[1], 64)
			//
			//		var categoryBoostScript *elasticSearch.ScriptFunction
			//
			//		//카테고리 부스팅 점수 음수값 삭제에 따라 음수값 판별 로직 제거(07.14)
			//		scriptString := fmt.Sprintf("doc[params.depth].value == params.category ? params.weight : 0")
			//		categoryBoostScript = elasticSearch.NewScriptFunction(elasticSearch.NewScript(scriptString).
			//			Param("weight", boostScore).Param("depth", categoryDepth).Param("category",category))
			//		mainFunctionQuery.AddScoreFunc(categoryBoostScript)
			//
			//	}
			//}

			scriptQuerys := product.GetBoostScriptQuery(boostDataArr)
			for _, query := range scriptQuerys {
				mainFunctionQuery.AddScoreFunc(query)
			}

			attributeValueSeqs := strings.Split(data["attributeValueSeqBoost"], " ")

			for _, value := range attributeValueSeqs {
				index := strings.LastIndex(value, ",")

				if index != -1 {
					weight := value[index+1:]
					floatValue, err := strconv.ParseFloat(weight, 64)

					if err != nil {
						fmt.Println("Error:", err)
					}

					attrs := value[:index]
					for _, val := range strings.Split(attrs, ",") {
						mainFunctionQuery.Add(elastic.NewTermQuery("nAttributeValueSeq", val), elastic.NewWeightFactorFunction(floatValue))
					}
				}
			}
		}

		if len(boostDataArr) > 0 {
			mainFunctionQuery.BoostMode("sum")
			mainFunctionQuery.ScoreMode("sum")
		}

	}

	//검색상품일때 collapse 쿼리 제외
	//count 쿼리에서는 필요
	if data["packageYN"] == "Y" {
		collaspeBuilder = elasticSearch.NewCollapseBuilder("bundleKey")
		//2021.06.08 : cadinalityAgg 정확도를 위한 precision_threshold 설정 (40000 ->  최대값)
		aggrs = elasticSearch.NewCardinalityAggregation().Field("bundleKey.hash").PrecisionThreshold(40000)
		innerHit = elasticSearch.NewInnerHit().Name("_bundle").Size(30)

		//count 쿼리의 경우 번들 내 필드,갯수, 정렬이 모두 필요 없다.
		if countYN == "Y" {
			innerHit.FetchSourceContext(elastic.NewFetchSourceContext(false))
			innerHit.Size(0)
		} else {
			innerHit.FetchSourceContext(elastic.NewFetchSourceContext(true).Include(sourceList...))
			if data["sort"] == "9" || data["sort"] == "4" || data["sort"] == "14" { // 인기상품순 || 신상품순 || 추천 신상품정렬
				sorter := elasticSearch.NewFieldSort("bundleName.field").UnmappedType("keyword").Asc()
				innerHit.Sort("bundleDisplaySequence", true).SortBy(sorter)
			} else {
				if fieldSorts != nil {
					innerHit.SortBy(fieldSorts...)
				}
			}
		}

		innerHit.Highlight(highlight)

// BrpsSettingEs2 : ES - 대표상품 변경
func BrpsSettingEs2(searchHit *elasticSearch.SearchHit, brpsFieldName string, sort int, quickPriceYN string) (source map[string]interface{}, highlight map[string]string) {
	source = make(map[string]interface{}, 0)
	highlight = make(map[string]string, 0)

	var bundleMap map[string]interface{}
	data := make(map[string]interface{}, 0)
	json.Unmarshal([]byte(searchHit.Source), &data)

	isBbrpsFieldName := brpsFieldName == "registerDateTime" || brpsFieldName == "manufactureDate" //

	if searchHit.InnerHits["_bundle"] != nil && (data["brps"] == "R" || isBbrpsFieldName) {
		// 검색 내부 정책 : 번들 시퀀스 비교해서 대표상품 지정 숫자가 작을 수록 우선
		// 만약 같은 경우 상품코드가 낮은 상품을 대표 상품으로 지정

		tempData := make(map[string]interface{}, 0)

		bundleSize := searchHit.InnerHits["_bundle"].Hits.TotalHits.Value

		bundle := searchHit.InnerHits["_bundle"].Hits.Hits

		if reflect.ValueOf(bundle).Kind() == reflect.Slice && bundleSize > 1 {
			tempData = nil
