// KeywordLengthCheck - godoc
func KeywordLengthCheck(keyword string) (isCheck bool) {

	keyword = html.UnescapeString(keyword)
	keyword = strings.TrimSpace(keyword) //  앞뒤에오는 공백 문자 제거

	if utf8.RuneCountInString(keyword) > 1 {
		isCheck = true
	} else if utf8.RuneCountInString(keyword) == 1 && len(keyword) > 1 { // 한글자 && 1바이트 초과 (자음, 모음)
		// utf8.RuneCountInString(keyword) == len([]rune(keyword)

		unicode, _ := utf8.DecodeRuneInString(keyword)
		char := unicode - 0xAC00

		if char >= 0 && char <= 11172 {
			isCheck = true
		} else {
			isCheck = false
		}
	} else {
		isCheck = false
	}

	return
}

// EngineErrorCheck godoc
func EngineErrorCheck(message string) (result map[string]interface{}) {
	//	result := make(map[string]interface{})

	if strings.Contains(message, "Error Code: 1004") {
		result["status"] = http.StatusRequestTimeout
		result["error_msg"] = "Search engine is under heavy load. - time out"
	} else if strings.Contains(message, "SocketTimeoutException") {
		result["status"] = http.StatusRequestTimeout
		result["error_msg"] = "java.net.SocketTimeoutException: Read timed out"
	} else {
		result["status"] = http.StatusBadRequest
		result["error_msg"] = "bad request"
	}

	return
}

